import sys, os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), ".."))
from common import PySet
P = PySet()
p = P.p

p("Vowels and consonants", "E", "strings", "vowel_consonant_counts", "s", "Return `[vowels, consonants]`, counting only English letters (case-insensitive; `aeiou` are vowels).", ["Skip non-letters."],
  "def vowel_consonant_counts(s):\n    v = c = 0\n    for ch in s.lower():\n        if ch.isalpha() and ch.isascii():\n            if ch in 'aeiou':\n                v += 1\n            else:\n                c += 1\n    return [v, c]", "Two counters.", [("Hello World",), ("aeiou",)], [("",), ("123!",), ("rhythm",), ("Python 3",)])
p("Smallest and largest digit", "E", "numbers", "digit_extremes", "n", "Return `[smallest digit, largest digit]` of the non-negative integer `n`.", ["Turn the number into digits."],
  "def digit_extremes(n):\n    ds = [int(c) for c in str(n)]\n    return [min(ds), max(ds)]", "Digits as a list.", [(4071,), (5,)], [(0,), (99,), (102030,), (987654,)])
p("All unique characters", "E", "sets", "all_unique_chars", "s", "Return `True` if no character appears twice in `s`.", ["Compare sizes of the string and its set."],
  "def all_unique_chars(s):\n    return len(set(s)) == len(s)", "Duplicates shrink the set.", [("abc",), ("hello",)], [("",), ("a",), ("Aa",), ("abcdefga",)])
p("Sum of two smallest", "E", "sorting", "sum_two_smallest", "nums", "Return the sum of the two smallest numbers in a list of at least two numbers (duplicates count separately).", ["Sort and add the first two."],
  "def sum_two_smallest(nums):\n    a, b = sorted(nums)[:2]\n    return a + b", "Sorted prefix.", [([5, 8, 12, 19, 22],), ([1, 1],)], [([3, 2],), ([-4, 9, -1],), ([10, 10, 10],)])
p("Maximum profit in job scheduling", "H", "dynamic-programming", "job_scheduling", "jobs", "Each job is `[start, end, profit]`. Choose non-overlapping jobs (a job may start exactly when another ends) to maximise total profit. Return that profit.", ["Sort by end time; binary search the last compatible job."],
  "def job_scheduling(jobs):\n    import bisect\n    jobs = sorted(jobs, key=lambda j: j[1])\n    ends = [j[1] for j in jobs]\n    dp = [0] * (len(jobs) + 1)\n    for i, (s, e, w) in enumerate(jobs):\n        k = bisect.bisect_right(ends, s, 0, i)\n        dp[i + 1] = max(dp[i], dp[k] + w)\n    return dp[-1]", "DP over jobs sorted by end.", [([[1, 3, 50], [2, 4, 10], [3, 5, 40], [3, 6, 70]],), ([[1, 2, 5]],)], [([],), ([[1, 2, 5], [2, 3, 6]],), ([[1, 5, 10], [2, 3, 6], [4, 6, 6]],), ([[1, 3, 20], [1, 3, 30]],)])
p("Find words in a grid", "H", "backtracking", "find_words_grid", "board, words", "Return the sorted list of words from `words` that can be traced in the letter grid through adjacent (up/down/left/right) cells without reusing a cell within a word.", ["DFS for each word, or a trie."],
  "def find_words_grid(board, words):\n    R, C = len(board), len(board[0])\n    def exists(word):\n        def go(r, c, i):\n            if i == len(word):\n                return True\n            if not (0 <= r < R and 0 <= c < C) or board[r][c] != word[i]:\n                return False\n            saved, board[r][c] = board[r][c], '#'\n            ok = any(go(r + dr, c + dc, i + 1) for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)))\n            board[r][c] = saved\n            return ok\n        return any(go(r, c, 0) for r in range(R) for c in range(C))\n    return sorted(w for w in set(words) if exists(w))", "Reuse the single-word search.", [([['o', 'a', 'a', 'n'], ['e', 't', 'a', 'e'], ['i', 'h', 'k', 'r'], ['i', 'f', 'l', 'v']], ['oath', 'pea', 'eat', 'rain']), ([['a', 'b'], ['c', 'd']], ['abcb'])], [([['a']], ['a', 'b']), ([['a', 'a']], ['aa', 'aaa']), ([['a', 'b'], ['c', 'd']], ['abdc', 'acdb', 'ad'])])
p("Minimum refueling stops", "H", "heaps", "min_refuel_stops", "target, start_fuel, stations", "A car starts with `start_fuel` and uses 1 fuel per mile. `stations` is a list of `[position, fuel]`, sorted by position. Return the minimum number of refuelling stops to reach `target`, or `-1`.", ["Greedy: refuel at the largest stations passed when you run out."],
  "def min_refuel_stops(target, start_fuel, stations):\n    import heapq\n    heap, stops, fuel, i = [], 0, start_fuel, 0\n    while fuel < target:\n        while i < len(stations) and stations[i][0] <= fuel:\n            heapq.heappush(heap, -stations[i][1])\n            i += 1\n        if not heap:\n            return -1\n        fuel += -heapq.heappop(heap)\n        stops += 1\n    return stops", "Delay the decision: take the biggest tank only when needed.", [(100, 10, [[10, 60], [20, 30], [30, 30], [60, 40]]), (1, 1, [])], [(100, 1, [[10, 100]]), (100, 50, [[25, 50]]), (50, 10, [[5, 5], [10, 40]])])
p("Shortest palindrome", "H", "strings", "shortest_palindrome", "s", "Add characters only at the **front** of `s` to make it a palindrome; return the shortest result.", ["Find the longest palindromic prefix."],
  "def shortest_palindrome(s):\n    for end in range(len(s), 0, -1):\n        if s[:end] == s[:end][::-1]:\n            return s[end:][::-1] + s\n    return s", "Reverse the non-palindromic suffix onto the front.", [("aacecaaa",), ("abcd",)], [("",), ("a",), ("aba",), ("ab",)])
